style.css:
@-moz-document domain("gesetze-im-internet.de") {
div {
        font-size: initial;
    }

    .jnheader h1 {
        font-size: 1.30em;
        margin-bottom: 24px;
        margin-top: 24px;
    }

    #blaettern_zurueck > a, #blaettern_weiter > a {
       text-decoration: none;
    }

    #fTop {
        display: none;
    }

    #blaettercontainer_2022, #content_blaettern_2022 {
        right: 0;
        left: 0;
        max-width: 800px;
        margin-left: auto;
        margin-right: auto;
    }

    #blaettercontainer_2022 {
        top: 150px;
    }

    #container {
        padding-top: 8px;
       padding-bottom: 32px;
        border-radius: 8px;
    }

    #fusszeile {
        max-width: 100vw;
        overflow-x: auto;
    }

    #fusszeile > li {
        width: max-content;
 	}
}
